enum.extra-code-model:

/** La clase de notificación de este canal. */
public Class<? extends Notificacion> getClaseNotificacion() {
    return switch (this) {
        case CORREO -> Correo.class;
        case SMS -> Sms.class;
    };
}

/** El canal de una clase de notificación; una clase que no es de ningún canal es un error de programación. */
public static TipoNotificacion deClase(Class<?> clase) {
    for (TipoNotificacion tipo : values()) {
        if (tipo.getClaseNotificacion().equals(clase)) {
            return tipo;
        }
    }
    throw new IllegalStateException("La clase " + clase.getName() + " no es de ningún canal de TipoNotificacion");
}
